package com.hospital.system.service; import com.hospital.system.model.*; import com.hospital.system.dto.*; import com.hospital.system.repository.*; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class BillingService {private final BillingRepository r; private final PatientRepository p; private final AppointmentRepository a; public BillingService(BillingRepository r,PatientRepository p,AppointmentRepository a){this.r=r;this.p=p;this.a=a;} public List<Bill> all(){return r.all();} public Bill one(Long id){Bill b=r.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Bill not found"));b.items=r.items(id);return b;} @Transactional public Bill create(BillRequest x){p.one(x.patientId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Patient not found"));if(x.appointmentId!=null)a.one(x.appointmentId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Appointment not found"));long id=r.create(x.patientId,x.appointmentId);return one(id);} @Transactional public Bill addItem(Long bill,BillItemRequest x){one(bill);var price=r.servicePrice(x.serviceId).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Active service not found"));r.addItem(bill,x.serviceId,x.quantity,price);return one(bill);} @Transactional public void removeItem(Long bill,Long item){one(bill);r.removeItem(bill,item);} }
